package com.own.promotion.coupon.repository;
import com.own.promotion.coupon.domain.MerchantCouponTemplate; import java.util.List; import javax.persistence.LockModeType; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query;
public interface MerchantCouponTemplateRepository extends JpaRepository<MerchantCouponTemplate, Long> { MerchantCouponTemplate findById(Long id); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select t from MerchantCouponTemplate t where t.id = ?1") MerchantCouponTemplate findByIdForUpdate(Long id); List<MerchantCouponTemplate> findByMerchantIdOrderByIdDesc(Long merchantId); }
